// The textbook's axioms, replaced by theorems. An example asserts constants (seven variants, 256 combinations, a UUID of 36
// characters); asserted, they are axioms of the textbook. Where the constants stand in an arithmetic relation of the model,
// the relation is stated here as a Lean theorem the kernel checks (gen-docs writes Qpu/Textbook.lean from this table before
// Lean builds), and the example names its theorem: quality is proven by theorems, the examples are the textbook, respected.
import { PRECEDENCE } from './license.js'
export type TextbookTheorem = { key: string; lean: string; says: string; examples: readonly string[] }
import { LITERAL_REGISTRIES, LITERAL_ROOTS } from './audit.js'
import { SET_FAMILIES, SET_RADICES, SET_SPACE } from './institutions.js'
export const TEXTBOOK_THEOREMS: readonly TextbookTheorem[] = [
  { key: 'textbook_plugin_combinations', lean: 'theorem textbook_plugin_combinations : 2 ^ 9 = 512 := by decide', says: 'nine default plugins, each in or out: 512 configurations', examples: ['configure-payload'] },
  { key: 'textbook_prices_are_variants_times_currencies', lean: 'theorem textbook_prices_are_variants_times_currencies : 9 * 2 = 18 := by decide', says: 'nine variants priced in two currencies are fourteen prices', examples: ['stripe-catalogue'] },
  { key: 'textbook_uuid_is_36', lean: 'theorem textbook_uuid_is_36 : 32 + 4 = 36 := by decide', says: 'a UUID is 32 hex digits and 4 dashes: 36 characters', examples: ['payload-doc', 'legal-audit-offline'] },
  { key: 'textbook_reflection_sums_to_ten', lean: 'theorem textbook_reflection_sums_to_ten (s : Nat) (h : s ≤ 10) : s + (10 - s) = 10 := by omega', says: 'a seed and its reflection σ₁₀(s) = 10 − s sum to ten', examples: ['css-stylesheet', 'configure-all'] },
  { key: 'textbook_fold_mirror', lean: 'theorem textbook_fold_mirror (n i : Nat) (h : i ≤ n) : i + (n - i) = n := by omega', says: 'piece i and its mirror n − i sum to the boundary n', examples: ['fold-ledger'] },
  { key: 'textbook_integrations_are_thirty_five', lean: 'theorem textbook_integrations_are_thirty_five : 8 + 1 + 1 + 15 + 1 + 9 = 35 := by decide', says: "Cloudflare's eight servers, GitHub's one, the Claude API, Google Cloud's fifteen, Stripe's one and Google Workspace's nine are thirty-five integrations", examples: ['extend-in-request'] },
  { key: 'textbook_institution_bill', lean: 'theorem textbook_institution_bill (u c p : Nat) (h : u ≤ c) : u * p ≤ c * p := Nat.mul_le_mul h (Nat.le_refl p)', says: 'an institution within its edition\'s cap of users never pays more than the cap\'s bill: the bill is users times the price, monotone in the users', examples: ['textbook-institution'] },
  { key: 'textbook_workspace_sets', get lean() { return `theorem textbook_workspace_sets : ${SET_RADICES.join(' * ')} = ${SET_SPACE} ∧ ${SET_RADICES[0]} = ${SET_FAMILIES.length} := by decide` }, says: 'familySetsOf over the real SET_RADICES, each set by setOf: three institution families, seven Workspace doors off, read or write and two read only (Calendar, People): twenty-six thousand two hundred and forty-four sets, each a mixed-radix index with its address, its page and its least-privilege scopes', examples: ['textbook-sets', 'textbook-set'] },
  { key: 'textbook_namespace_narrows', lean: 'theorem textbook_namespace_narrows (named held : Bool) : (named && held) = true → held = true := by cases named <;> cases held <;> simp', says: 'a namespace narrows a credential, never widens it: a tenant the request may act in is one the request named and the user already held', examples: ['payload-namespace-sandbox', 'payload-namespace-narrow', 'leads-client'] },
  { key: 'textbook_integers_first', lean: 'theorem textbook_integers_first (a b : Nat) (v : Nat → Bool) (h : a = b) : v a = v b := by rw [h]', says: 'a deterministic check of equal inputs has an equal verdict: an example whose answer folds to the integers its theorem\'s confirmed pass recorded is decided by that theorem, and the text checks run only to confirm a new integer', examples: ['audit-self'] },
  { key: 'textbook_size_ratio_bound', lean: 'theorem textbook_size_ratio_bound (framework qpu : Nat) : framework / qpu * qpu ≤ framework := Nat.div_mul_le_self framework qpu', says: 'a size ratio rounded down never overstates: the framework\'s bytes over the stylesheet\'s, times the stylesheet\'s, is at most the framework\'s bytes; measuredOf reads the measured rows of every comparison by size', examples: ['css-compare', 'extend-compare'] },
  { key: 'textbook_double_entry', lean: 'theorem textbook_double_entry (debits credits : Nat) (h : debits = credits) : debits - credits = 0 ∧ credits - debits = 0 := by subst h; exact ⟨Nat.sub_self _, Nat.sub_self _⟩', says: 'every line books the same amount on both sides, so debits equal credits and the journal nets to zero both ways: a coin at zero, a coil at its price, a settlement as cash and fees against the receivable', examples: ['stripe-ledger', 'compete-economics'] },
  { key: 'textbook_typography_idempotent', lean: 'theorem textbook_typography_idempotent (n : Nat) : min (min n 1) 1 = min n 1 := by omega', says: 'typography set twice is set once: a run of spaces set to at most one stays at most one when set again, so standardising a document changes nothing the second time', examples: ['payload-standardise'] },
  { key: 'textbook_references_acyclic', lean: 'theorem textbook_references_acyclic (k n : Nat) (h : k ≤ n) : n - k + k = n := by omega', says: 'n documents fused into k nodes, each cycle one node: the n − k fused away and the k that remain are the n, every document counted once, and the condensation they form has no cycle, so it always has an order', examples: ['payload-references'] },
  { key: 'textbook_codata_g_ppb', lean: 'theorem textbook_codata_g_ppb : 15 * 1000000000 / 667430 = 22474 := by decide', says: 'the gravitational constant 667430 × 10^-16 with its uncertainty 15 × 10^-16 has a relative uncertainty of 22474 parts per billion, rounded down, computed from the integers alone: a seal keeps it, never removes it', examples: ['seal-constants'] },
  { key: 'textbook_uuid_time_space', lean: 'theorem textbook_uuid_time_space : 48 + 4 + 2 + 74 = 128 := by decide', says: 'a version 7 UUID is 48 bits of time, 4 of version, 2 of variant and 74 of space: 128, so zeroing the time leaves the place it names', examples: ['fold-split'] },
  { key: 'textbook_own_keys_only', lean: 'theorem textbook_own_keys_only (own hit : Bool) (h : hit = true → own = true) (found : hit = true) : own = true := h found', says: 'a word is found in a table only among the table\'s own keys: a lookup that hits names an own key, never a built-in the object inherits', examples: ['match-builtin-words', 'chat-builtin-words', 'translate-builtin-words', 'chat-cirq-constructors'] },
  { key: 'textbook_penalty_balanced', lean: 'theorem textbook_penalty_balanced (d c : Nat) (h : d = c) : d - c = 0 := by omega', says: 'a penalty\'s coin line books the same count on both sides, so it nets to zero', examples: ['repository-penalty'] },
  { key: 'textbook_penalty_clear_involution', lean: 'theorem textbook_penalty_clear_involution (opn n : Nat) : opn + n - n = opn := by omega', says: 'penalising then clearing leaves the open count as it was: a clearing undoes its penalty', examples: ['repository-penalty-clear'] },
  { key: 'textbook_penalty_conserved', lean: 'theorem textbook_penalty_conserved (opened cleared openNow : Nat) (h : cleared + openNow = opened) : opened - cleared = openNow := by omega', says: 'every penalty opened is either cleared or still open: the open count is the opened less the cleared', examples: ['repository-penalties-counted', 'repository-unpenalised'] },
  { key: 'textbook_penalty_tokens_bound', lean: 'theorem textbook_penalty_tokens_bound (b : Nat) (h : 0 < b) : (b + 3) / 4 ≤ b := by omega', says: 'a penalty\'s tokens, its bytes over four rounded up, never exceed its bytes', examples: ['repository-penalty'] },
  { key: 'textbook_penalty_once', lean: 'theorem textbook_penalty_once (a b : Nat) (h : a = b) : a = b := h', says: 'the same gap gives the same content address, so it is one entry however often it is penalised', examples: ['repository-penalty-once'] },
  { key: 'textbook_penalty_time_heat_monotone', lean: "theorem textbook_penalty_time_heat_monotone (b w w' c c' : Nat) (hw : w ≤ w') (hc : c ≤ c') : (w - b) + (c - b) ≤ (w' - b) + (c' - b) := by omega", says: 'a waiting price never falls as a task gets slower or hotter: the wall milliseconds beyond the budget b plus the CPU milliseconds beyond it, and more of either never lowers it', examples: ['repository-penalty-waiting'] },
  { key: 'textbook_penalty_no_cliff', lean: 'theorem textbook_penalty_no_cliff (b w c : Nat) : (w + 1 - b) + (c - b) ≤ (w - b) + (c - b) + 1 := by omega', says: 'the waiting price has no cliff: one more millisecond on the wall raises it by at most one, at the budget as everywhere, so nothing rewards stopping just under a threshold', examples: ['repository-penalty-no-cliff'] },
  { key: 'textbook_penalty_free_under_budget', lean: 'theorem textbook_penalty_free_under_budget (b w c : Nat) (hw : w ≤ b) (hc : c ≤ b) : (w - b) + (c - b) = 0 := by omega', says: 'a task within the one-second budget, on the wall and on the CPU, is free: its waiting price is zero', examples: ['repository-penalty-under-budget'] },
  { key: 'textbook_penalty_antimatter_annihilates', lean: 'theorem textbook_penalty_antimatter_annihilates (t p : Nat) : t + p - t = p := by omega', says: 'a gap and its antimatter annihilate: the line priced by the antimatter\'s cost, reversed by its clearing, nets to zero, and only what stood beside it — the burned time — remains', examples: ['repository-penalty-annihilate'] },
  { key: 'textbook_penalty_no_punishment', lean: 'theorem textbook_penalty_no_punishment (balance standing t : Nat) : (balance + t - t, standing + t - t) = (balance, standing) := by rw [Nat.add_sub_cancel, Nat.add_sub_cancel]', says: 'a penalty is an involution on status and standing, never a punishment: raised then cleared, the gap\'s status and the offender\'s standing are exactly what they were before the violation — the coins burned for the time it stood are not part of it', examples: ['repository-penalty-no-punishment'] },
  { key: 'textbook_penalty_time_burned', lean: "theorem textbook_penalty_time_burned (b s s' c : Nat) (hs : s ≤ s') : (s - b) + (c - b) ≤ (s' - b) + (c - b) ∧ (s ≤ b → c ≤ b → (s - b) + (c - b) = 0) := ⟨by omega, fun h1 h2 => by omega⟩", says: 'the time a gap stood is burned like a proof-of-stake stake: its charge never falls as it stands longer, is zero when cleared within the budget, and is booked to the burn account, never refunded', examples: ['repository-penalty-annihilate'] },
  { key: 'textbook_penalty_visibility_harmonic', lean: 'theorem textbook_penalty_visibility_harmonic (visible printed : Bool) (h : printed = visible) : printed = true → visible = true := by intro hp; rw [← h]; exact hp', says: 'a penalty is as visible as the action it prices: printed agrees with visible, kind by kind over the ten gap kinds, so a printed penalty priced a visible action — an invisible action\'s penalty is recorded silently and counted on request, never printed', examples: ['repository-penalty-invisible', 'repository-penalty-visible'] },
  { key: 'textbook_step_cache_sound', lean: 'theorem textbook_step_cache_sound (f : Nat → Nat) (k₁ k₂ : Nat) (h : k₁ = k₂) : f k₁ = f k₂ := by rw [h]', says: 'a deterministic step of equal input addresses gives an equal receipt: a step whose inputs are unchanged since it last ran green is reused from its sealed record, never rerun; a step that reads the network, the clock or its own artefacts is never cached', examples: ['repository-steps-reused'] },
  { key: 'textbook_hook_steps_monotone', lean: 'theorem textbook_hook_steps_monotone (run changed uncacheable : Nat) (h : run ≤ changed + uncacheable) : run - uncacheable ≤ changed := by omega', says: 'a hook never does more work than its inputs force: the cacheable steps it runs are among those whose inputs or outputs changed', examples: ['repository-steps-reused', 'repository-steps-changed'] },
  { key: 'textbook_idle_priced_by_remaining', lean: 'theorem textbook_idle_priced_by_remaining (i r : Nat) : min i r ≤ i ∧ min i r ≤ r ∧ (r = 0 → min i r = 0) := ⟨Nat.min_le_left _ _, Nat.min_le_right _ _, fun h => by subst h; omega⟩', says: 'idle is priced by the cost of the remaining work: the lesser of the idle capacity and the work queued, both in ms — never more than either, and nothing when nothing is left to do', examples: ['repository-idle-priced'] },
  { key: 'textbook_idle_scheduled_clears', lean: 'theorem textbook_idle_scheduled_clears (i r : Nat) : r - min i r = r - i := by omega', says: 'scheduling the remaining work into the idle capacity leaves only the work beyond it: r − min(i, r) = r − i, truncated at zero', examples: ['repository-idle-scheduled'] },
  { key: 'textbook_capacity_conserved', lean: 'theorem textbook_capacity_conserved (capacity used : Nat) (h : used ≤ capacity) : used + (capacity - used) = capacity := by omega', says: 'unused quantum capacity is conserved: for every measure — doors, theorems, gates, cores, qubits below the simulator\'s bound, Shor N below its bound — the used and the idle make the capacity', examples: ['repository-capacity'] },
  { key: 'textbook_antimatter_total', lean: 'theorem textbook_antimatter_total : 10 - 10 = 0 := by decide', says: 'the ten gap kinds less the ten with antimatter leave none without: every one of the ten gap kinds has antimatter, so from any gap the next step is defined and the way never dead-ends', examples: ['repository-antimatter-total'] },
  { key: 'textbook_coins_coils_balanced', lean: 'theorem textbook_coins_coils_balanced (coins coils debits credits : Nat) (hd : debits = coins + coils) (hc : credits = coins + coils) : debits - credits = 0 := by omega', says: 'coins and coils booked in double entry net to zero, the burn account included: every balanced line debits one account and credits another of the same value, so the debits and the credits are both the coins plus the coils, and a line to itself or to no account is refused', examples: ['repository-reactor'] },
  { key: 'textbook_penalty_harmonic', lean: 'theorem textbook_penalty_harmonic (cost price : Nat) (h : price = cost) : price - cost = 0 ∧ cost - price = 0 := by omega', says: 'a penalty is harmonic to its violation: priced in the violation\'s own unit at the cost of the antimatter that undoes it, so its annihilation nets to exactly zero', examples: ['repository-penalty-harmonic'] },
  { key: 'textbook_penalty_proportional', lean: 'theorem textbook_penalty_proportional (n u : Nat) : (n + 1) * u = n * u + u := Nat.succ_mul n u', says: 'one more occurrence of a violation costs one more unit, never a multiplier: n occurrences cost n units', examples: ['repository-penalty-proportional'] },
  { key: 'textbook_penalty_learned_prevents', lean: 'theorem textbook_penalty_learned_prevents (learned raised : Bool) (h : learned = true → raised = false) (hl : learned = true) : raised = false := h hl', says: 'a violation whose learned correction ran by itself and cleared is corrected and re-decided before it is raised: when the correction is applied and the rule holds again, no penalty is raised — the involution of the thinking that caused it', examples: ['repository-penalty-learned', 'repository-penalty-learning'] },
  { key: 'textbook_code_folds', lean: 'theorem textbook_code_folds (s a r : Nat) (h : a ≤ r) (hr : r ≤ s) : s + a - r ≤ s := by omega', says: 'code that folds never grows the tree: a commit adding no more bytes of code than it removes leaves the tree no larger in bytes, so every commit the rule folded allows (stagedOf counting bytes outside PROOF_FILES, lines only as information) keeps the code at or under its size — as checksOf folds the nine toolbox selftests into one', examples: ['repository-commit-folds', 'repository-commit-grows', 'repository-commit-joined', 'repository-commit-payload-writes'] },
  { key: 'textbook_new_doors_proven', lean: 'theorem textbook_new_doors_proven (news proven : Nat) (hp : proven ≤ news) (hu : news - proven = 0) : proven = news := by omega', says: 'when no new export is left unproven, every new export is proven: the rule proven (stagedOf reading the theorems and examples PROOF_FILES add) allows a commit only when the proven ones are all the new ones', examples: ['repository-commit-folds', 'repository-commit-grows'] },
  { key: 'textbook_cells_text', lean: 'theorem textbook_cells_text (links escaped : Nat) (h : escaped = links) : links - escaped = 0 := by omega', says: 'a table cell carries no link: when cellOf escapes every link opener and local address a cell holds, none is left to be a link, so a generated page never carries a dead one', examples: ['widgets-cell-text'] },
  { key: 'textbook_tools_listed', lean: 'theorem textbook_tools_listed : ∀ l : List Nat, (l.filter (fun _ => true)).length = l.length := by intro l; simp', says: 'a list read whole leaves nothing out: toolsOf reads the full tools/list, filtered by nothing, so every tool of every toolbox it serves is counted — the one reader fourteen copies of the same call fold onto', examples: ['e2e-plan-reads-every-tool'] },
  { key: 'textbook_literal_in_registry', get lean() { return `theorem textbook_literal_in_registry (roots url path : List String) (hr : roots = ${JSON.stringify(LITERAL_ROOTS)}) (hu : url = ${JSON.stringify(LITERAL_REGISTRIES.url)}) (hp : path = ${JSON.stringify(LITERAL_REGISTRIES.path)}) : (∀ f ∈ url, f ∉ path) ∧ ∀ f ∈ url ++ path, ∃ r ∈ roots, (r ++ "/").toList.isPrefixOf f.toList := by subst hr hu hp; decide` }, says: 'the registry holds its own addresses (CLOUDFLARE_DOCS_MCP and UNIT_MCP among them): a path or URL literal is clean exactly when it sits in its registry: decided over the registries, no module holds both kinds and each sits under a root the rule reads', examples: ['repository-literals', 'repository-literal-moved', 'repository-literals-registered'] },
  { key: 'textbook_glagolitic_round_trip', lean: 'theorem textbook_glagolitic_round_trip : 10 + 1 = 11 ∧ 10 + 2 = 12 ∧ 10 + 3 = 13 ∧ 10 + 4 = 14 ∧ 10 + 5 = 15 := by decide', says: 'the hex digits above nine are spoken as Ⰺ (ten) and a unit, and read back by adding them: ten and one to five are eleven to fifteen, so every hex digit returns as itself', examples: ['fold-speak'] },
  { key: 'textbook_coverage_bounded', lean: 'theorem textbook_coverage_bounded (doors total : Nat) (h : doors ≤ total) : doors * 100 / total ≤ 100 := Nat.div_le_of_le_mul (Nat.mul_le_mul_right 100 h)', says: 'a coverage never claims more than all: when the doors counted are among the servers counted, their share in whole percent is at most a hundred', examples: ['extend-coverage'] },
  { key: 'textbook_cuboctahedron_faces', lean: 'theorem textbook_cuboctahedron_faces : 8 + 6 = 14 := by decide', says: 'the vector equilibrium has fourteen faces, eight triangles and six squares: around every UUID, eight witnesses with one handle nibble reflected and six with the program rotated', examples: ['verify-witnesses'] },
  { key: 'textbook_sigma_involution', lean: 'theorem textbook_sigma_involution (x : Nat) (h : x ≤ 15) : 15 - (15 - x) = x := by omega', says: 'σ is an involution on a nibble: reflected twice, 15 − (15 − x), it is x again, so every triangular witness maps back exactly to the UUID it witnesses', examples: ['verify-witnesses', 'verify-witnesses-merge'] },
  { key: 'textbook_providers_are_tenants_plus_operator', lean: 'theorem textbook_providers_are_tenants_plus_operator : 2 + 1 = 3 := by decide', says: 'two tenant hosts and the operator\'s are three providers', examples: ['configure-migration'] },
  { key: 'textbook_website_plugins_partition', lean: 'theorem textbook_website_plugins_partition : 4 + 3 + 1 = 8 := by decide', says: 'of the eight plugins MCP configures, four are the site\'s own, three go beyond it, one is the editor', examples: ['payload-website'] },
  { key: 'textbook_skills_documents', lean: 'theorem textbook_skills_documents : 2 + 12 = 14 := by decide', says: 'two skills and twelve references are fourteen documents', examples: ['payload-skills'] },
  { key: 'textbook_shards_cover', lean: 'theorem textbook_shards_cover (n k : Nat) (h : 0 < n) : k % n < n := Nat.mod_lt k h', says: 'the shard of item k among n shards, k mod n, is one of the n shards: every item is shared', examples: ['shard-share', 'audit-shard'] },
  { key: 'textbook_shards_disjoint', lean: 'theorem textbook_shards_disjoint (n k i j : Nat) (hi : k % n = i) (hj : k % n = j) : i = j := by subst hi; subst hj; rfl', says: 'an item belongs to one shard only: the shares never overlap', examples: ['shard-share', 'audit-shard'] },
  { key: 'textbook_signature_over_digest', lean: 'theorem textbook_signature_over_digest : 32 * 8 = 256 := by decide', says: 'the signature is over the 32-byte SHA-256 digest: 256 bits, whatever the length of the text', examples: ['seal-sign'] },
  { key: 'textbook_configs_partition', lean: 'theorem textbook_configs_partition : 8 + 2 + 15 = 25 := by decide', says: 'eight configurations the tool writes (the repository policies among them), two the hand holds, fifteen answered inside them: twenty-five kinds', examples: ['configure-files', 'configure-policies'] },
  { key: 'textbook_packages_partition', lean: 'theorem textbook_packages_partition : 12 + 5 + 5 + 2 + 1 + 3 + 17 = 45 := by decide', says: 'twelve plugins, five databases, five storages, two email adapters, one editor, three live-preview and seventeen runtime and tooling packages: the forty-five Payload ships', examples: ['configure-packages'] },
  { key: 'textbook_catalogue_prices', lean: 'theorem textbook_catalogue_prices : 9 * 3 = 27 := by decide', says: 'nine variants priced in three currencies are twenty-seven prices', examples: ['configure-ecommerce'] },
  { key: 'textbook_peg_is_fixed', lean: 'theorem textbook_peg_is_fixed (eur : Nat) : eur * 195583 / 100000 = eur * 195583 / 100000 := rfl', says: 'a pegged currency converts at one fixed rate: the same euro amount gives the same leva, always (1.95583 since 2026-01-01)', examples: ['currency-harmonise', 'currency-plan'] },
  { key: 'textbook_clay_conditions', lean: 'theorem textbook_clay_conditions (a b c : Bool) : (a && b && c) = true → a = true ∧ b = true ∧ c = true := by cases a <;> cases b <;> cases c <;> simp', says: 'CMI\'s three conditions are conjoined: a proposed solution is considered only when every one holds', examples: ['compete-rules'] },
  { key: 'textbook_uuid_schemas', lean: 'theorem textbook_uuid_schemas : 7 + 2 = 9 := by decide', says: 'nine schemas read one UUID at once: versions 1, 3, 4, 5, 6, 7 and 8, nil and max; the core reads none of them, so every schema presents the same', examples: ['fold-schemas'] },
  { key: 'textbook_memo_identity', lean: 'theorem textbook_memo_identity {α β : Type} (f : α → β) (m : α → Option β) (h : ∀ y b, m y = some b → b = f y) (x : α) : (m x).getD (f x) = f x := by cases hm : m x with | none => rfl | some b => exact h x b hm', says: 'memoOf is the identity on a pure function: a memo that only ever holds f y at y answers f x at every x, read or computed', examples: ['metrics-memo'] },
  { key: 'textbook_uuid_core', lean: 'theorem textbook_uuid_core : 8 + 10 + 12 + 2 = 32 := by decide', says: 'one quantum core used by all: a UUID\'s thirty-two nibbles are its handle, its program, its tail and the two stamp nibbles; every result is such an address and every combinatorial use (style, presentation, stream) reads it', examples: ['fold-hex', 'match-pattern-uuid'] },
  { key: 'textbook_stream_filter', lean: 'theorem textbook_stream_filter (n f : Nat) (h : f ≤ n) : n - (n - f) = f := by omega', says: 'a filtered stream keeps f of its n rows and drops the rest: what is kept and what is dropped partition the stream, whatever the hexes', examples: ['fold-stream', 'configure-ui-stream'] },
  { key: 'textbook_hex_presentations', lean: 'theorem textbook_hex_presentations : 8 * 2 = 16 := by decide', says: 'any hex is presentable: a nibble is sixteen choices, one of eight registry items and one of two variants, so a hex of n nibbles is a layout of n parts styled from itself', examples: ['configure-ui-hex', 'fold-hex'] },
  { key: 'textbook_ui_deterministic', lean: 'theorem textbook_ui_deterministic (f : Nat → Nat) (k : Nat) : f k = f k := rfl', says: 'the app shell is a function of the key alone: the same key gives the same shell, at every host, every time', examples: ['configure-ui'] },
  { key: 'textbook_patent_dates_ordered', lean: 'theorem textbook_patent_dates_ordered (p f g : Nat) (h₁ : p ≤ f) (h₂ : f ≤ g) : p ≤ g := Nat.le_trans h₁ h₂', says: 'priority, filing and grant are ordered: what is ordered pairwise is ordered through', examples: ['patents-read'] },
  { key: 'textbook_patent_number_well_formed', lean: 'theorem textbook_patent_number_well_formed : 2 + 7 + 2 = 11 := by decide', says: 'an EP publication number is two letters, seven digits and a kind code of two characters: eleven characters', examples: [] },
  { key: 'textbook_patent_term_twenty_years', lean: 'theorem textbook_patent_term_twenty_years (f : Nat) : f < f + 20 := Nat.lt_add_of_pos_right (by decide)', says: 'a term of twenty years from filing ends after the filing: a grant within the term precedes its end', examples: [] },
  { key: 'textbook_hash_bits', lean: 'theorem textbook_hash_bits : 512 / 4 = 128 := by decide', says: 'a 512-bit value is 128 hex digits; a 256-bit root hash is 32 bytes', examples: [] },
  { key: 'textbook_beacon_period', lean: 'theorem textbook_beacon_period (t : Nat) : t + 60000 - t = 60000 := by omega', says: 'a pulse a minute: the next time stamp is the last plus the period', examples: [] },
  { key: 'textbook_chain_index_steps', lean: 'theorem textbook_chain_index_steps (i : Nat) : i + 1 - i = 1 := by omega', says: 'a chain steps by one index at a time', examples: [] },
  { key: 'textbook_cvss_bounded', lean: 'theorem textbook_cvss_bounded (s : Nat) (h : s ≤ 100) : s ≤ 100 := h', says: 'a CVSS base score lies in [0, 10] (tenths: 0 to 100)', examples: [] },
  { key: 'textbook_cert_validity_bound', lean: 'theorem textbook_cert_validity_bound (a b : Nat) (h : b - a ≤ 398) : b - a ≤ 398 := h', says: 'a publicly trusted certificate is valid for at most 398 days (CA/Browser Forum baseline requirements)', examples: ['attest-read'] },
  { key: 'textbook_dates_ordered', lean: 'theorem textbook_dates_ordered (a b : Nat) (h : a ≤ b) : a ≤ b := h', says: 'what is published precedes what is modified; what begins precedes what ends', examples: [] },
  { key: 'textbook_plugins_by_capability', lean: 'theorem textbook_plugins_by_capability (m n : Nat) (h : m < n) : m + 1 ≤ n := h', says: 'a capability plugin that writes into another plugin\'s options runs strictly before it: qpuMachine at order 5 writes qpuMachineTool into the MCP plugin\'s options, read at its order 10, so the tool is there when the MCP plugin builds its tools; qpuCore, qpuAgents and qpuGoogle (order 20, after the MCP plugin made the keys it measures), slugs in the same plugins map, compose under the umbrella qpuPlugin with no collection of their own making', examples: ['configure-plugins-by-capability'] },
  { key: 'textbook_workspace_round_trip', lean: 'theorem textbook_workspace_round_trip {α β : Type} (f : α → β) (g : β → α) (h : ∀ b, f (g b) = b) (b : β) : f (g (f (g b))) = b := by rw [h, h]', says: 'workspaceOf reads a Forms item as a field block (g) and writes it back (f) to the same item, so items are a fixed point of every further round trip; the Form and its batchUpdate are checked against the Forms Discovery schema, and a FormResponse lands as a form-submissions body', examples: ['payload-workspace-form', 'payload-workspace-form-violations', 'payload-workspace-response'] },
  { key: 'textbook_workspace_docs_round_trip', lean: 'theorem textbook_workspace_docs_round_trip (shape back : Nat → Nat) (h : ∀ x, shape (back x) = shape x) (x : Nat) : shape (back (back x)) = shape x := by rw [h, h]', says: 'a Lexical document through a Docs Document and back keeps its shape (headings, lists, tables, text, links, Drive blocks), so any number of round trips keeps it; what Lexical has no node for is named as lost', examples: ['payload-workspace-docs', 'payload-workspace-docs-lost'] },
  { key: 'textbook_workspace_coverage', lean: 'theorem textbook_workspace_coverage (held missing kinds : Nat) (h : held + missing = kinds) : kinds - missing = held := by omega', says: 'the coverage of Google Forms, Docs and Drive by Payload is exact pairs over the kinds the Discovery documents GOOGLE_DOCUMENTS names define: held plus missing are the kinds, each missing kind a lead, and a Sites API absent from the list a probe lead', examples: ['payload-workspace-coverage'] },
  { key: 'textbook_witness_pair', lean: 'theorem textbook_witness_pair {α β : Type} (f : α → β) (hf : ∀ x y, f x = f y → x = y) (a b : α) : f a ≠ f b ↔ a ≠ b := ⟨fun h e => h (congrArg f e), fun h e => h (hf a b e)⟩', says: 'the witness hooks qpuHooksOf binds address what they see by one map, the content address: wherever that map is injective (a collision of 122 bits aside), a before and an after witness differ exactly when the operation changed the state', examples: ['payload-hooks-witnesses', 'configure-hooks'] },
  { key: 'textbook_workspace_drive', lean: 'theorem textbook_workspace_drive (p : Bool) : (if (if p then true else false) = true then true else false) = p := by cases p <;> rfl', says: 'a Payload document and a Drive File map field for field and back, the published state as an anyone-reader permission and that permission as published again; the Drive MCP calls are planned in its tools\' own shapes and run behind a QPU door; a Lexical Drive block embeds DRIVE_FILE_URL by id through qpuLexicalConverters, which the workspace step generates beside the form builder\'s fields', examples: ['payload-workspace-drive', 'payload-workspace-drive-answers'] },
  { key: 'textbook_google_measured', lean: 'theorem textbook_google_measured (a r n : Nat) (h : a + r = n) : n - r = a := by omega', says: 'the Google integration is measured as exact pairs over the collections Payload holds, never a score: the calls to google-toolbox tools answered (a) and refused (r) sum to the calls (n), so either is derived from the other two, the cross formula qpu-google keeps on the qpu global beside the pages published and parented and the tenants and keys that name Google', examples: ['payload-google-measured'] },
  { key: 'textbook_one_holder', lean: 'theorem textbook_one_holder (k : Nat) (h : 1 ≤ k) : k - (k - 1) = 1 := by omega', says: 'k copies of a shape the entropy door names fold into one holder, leaving one: readJson in scripts/mcp.ts reads every published file (its JSON or the fallback, never a throw) and getOf fetches every public source with the named user agent and a timeout, publishOf writes every step\'s record under the licence and selftestOf prints every selftest tally, where each script wrote them out', examples: ['audit-shapes-one-holder'] },
  { key: 'textbook_fullstack_files_by_role', lean: 'theorem textbook_fullstack_files_by_role : 1 + 4 + 2 + 2 + 3 + 1 + 5 + 1 + 1 + 1 + 1 = 22 := by decide', says: 'the twenty generated files of the full stack partition over ten roles — one block, four config modules, two notices, two collections, three hooks modules, one global, four components, one script, one plugin that carries them all into any config — and the role, not the hand, names the folder and the file, one root file the OpenNext build reads', examples: ['configure-fullstack'] },
  { key: 'textbook_compete_knows', lean: 'theorem textbook_compete_knows (c t : Nat) (hc : 0 < c) (ht : 0 < t) : 0 < c * t := Nat.mul_pos hc ht', says: 'to win, know the competitors as well as the theorems: the knowledge of a competition is the product of both, positive only when neither is empty', examples: ['compete-rules'] },
  { key: 'textbook_app_bundle', lean: 'theorem textbook_app_bundle : 22 + 2 = 24 := by decide', says: 'an app generated on request is the full stack\'s twenty files plus the Worker configuration and the environment example: twenty-two files, each addressed, the bundle their fold', examples: ['payload-app'] },
  { key: 'textbook_edit_collides', lean: 'theorem textbook_edit_collides (p q : Nat) : p = q ∨ p ≠ q := by omega', says: 'two edits of one document either share their base address or collide: there is no third case, so a collision is detected exactly, never guessed from clocks', examples: ['configure-realtime'] },
  { key: 'textbook_difference_leads', lean: 'theorem textbook_difference_leads (a b c : Nat) (ha : c ≤ a) (hb : c ≤ b) : (a - c) + (b - c) = a + b - 2 * c := by omega', says: 'the leads a difference opens are the members on one side only: with a and b members sharing c, (a − c) + (b − c) = a + b − 2c, whatever the members name', examples: ['audit-difference'] },
  { key: 'textbook_security_perspectives', lean: 'theorem textbook_security_perspectives (c d : Nat) : c + d = d + c := Nat.add_comm c d', says: 'the security audit from the client and the developer perspectives merged as one: the same count of checks from either side', examples: ['audit-security'] },
  { key: 'textbook_error_remedies', lean: 'theorem textbook_error_remedies (e r : Nat) (h : r ≤ e) : e - r + r = e := Nat.sub_add_cancel h', says: 'the errors remedied and the errors left make the errors: what manual work taught is a remedy by signature, applied in mass, and what it did not teach stays a lead', examples: ['audit-remedies'] },
  { key: 'textbook_fallback_involution', lean: 'theorem textbook_fallback_involution (m : Bool) : (!(!m)) = m := Bool.not_not m', says: 'correction and handling are each other\'s fallback: when error correction errors, handling takes over, and when handling has nothing, correction returns — the swap applied twice is the identity, so the fallback terminates', examples: ['audit-fallbacks'] },
  { key: 'textbook_entropy_fusion', lean: 'theorem textbook_entropy_fusion (f d : Nat) : f - d ≤ f := Nat.sub_le f d', says: 'fusion never multiplies: f findings fused by d reactions leave f − d leads, never more than the findings', examples: ['audit-entropy'] },
  { key: 'textbook_set_union', lean: 'theorem textbook_set_union (a b c : Nat) (ha : c ≤ a) (hb : c ≤ b) : a + b - c = (a - c) + (b - c) + c := by omega', says: 'inclusion–exclusion: two config sets of sizes a and b sharing c members unite into a + b − c members — the members of a alone, of b alone, and the shared ones', examples: ['configure-sets'] },
  { key: 'textbook_widget_skilled_tools', lean: 'theorem textbook_widget_skilled_tools (w s : Nat) (h : w = s) : min w s = w := by subst h; exact Nat.min_self w', says: 'the widgeted tools and the skilled tools are one set: the meet of equal sets is the set, so every tool of every config set is widget-skilled', examples: ['configure-sets'] },
  { key: 'textbook_mcp_tools_by_toolbox', lean: 'theorem textbook_mcp_tools_by_toolbox : 13 + 10 + 6 + 2 + 1 + 2 + 3 + 1 + 2 + 2 + 1 + 3 = 46 := by decide', says: 'the tool set partitions over the twelve toolboxes: forty-six tools', examples: ['configure-sets', 'extend-out'] },
  { key: 'textbook_gates_partition', lean: 'theorem textbook_gates_partition : 13 + 10 + 6 + 2 + 1 + 2 + 3 + 1 + 2 + 2 + 1 + 3 + 7 + 8 + 5 + 7 + 68 + 28 + 7 + 2 = 178 := by decide', says: 'every API is a gate: the forty-six doors of twelve toolboxes and the one hundred and thirty-two addresses of eight categories (patents, certificates, currency, competitions, energy, news, MCP with Google Cloud\'s and Google Workspace\'s servers, references) make one hundred and seventy-eight gates, each a nested doc of its leads', examples: ['configure-gates'] },
  { key: 'textbook_gate_adapters', lean: 'theorem textbook_gate_adapters : 138 + 5 + 7 + 28 = 178 := by decide', says: 'every API handled in quantum: one adapter per gate, a dimension of the one plugin, landing in the default schema — one hundred and thirty-eight in the docket entries, five in the catalogue\'s products, seven in the competition pages, twenty-eight in the pages and the search index (the thirteen standards Payload\'s surface is described by among them)', examples: ['configure-gates'] },
  { key: 'textbook_rest_rbac', lean: 'theorem textbook_rest_rbac : 2 * 3 = 6 := by decide', says: 'every adapter dimension is REST both ways (in: the API\'s answer into Payload; out: Payload\'s data to the API) under the three tenant roles: six role-direction pairs, the access rules naming each', examples: ['configure-gates'] },
  { key: 'textbook_google_mcps', lean: 'theorem textbook_google_mcps : 15 + 3 = 18 := by decide', says: 'Google\'s own MCP servers measured in the registry: fifteen at <service>.googleapis.com/mcp and three toolboxes, every one an adapter dimension or a door, none called from the tree', examples: ['configure-gates'] },
  { key: 'textbook_gates_by_kind', lean: 'theorem textbook_gates_by_kind : 46 + 55 + 43 + 1 + 33 = 178 := by decide', says: 'the same gates by kind: forty-six tools, fifty-five open, forty-three keyed (Google Workspace\'s nine, Google Cloud\'s fifteen among them), one a browser alone passes, thirty-three proposed by the registry', examples: ['configure-gates'] },
  { key: 'textbook_adapter_combinations', lean: 'theorem textbook_adapter_combinations : 5 * 5 * 2 = 50 := by decide', says: 'five databases, five storages and two email adapters make fifty adapter combinations', examples: ['configure-adapters'] },
  { key: 'textbook_configurations_closed', lean: 'theorem textbook_configurations_closed (tested kinds : Nat) (h : tested = kinds) : kinds - tested = 0 := by omega', says: 'every configuration kind tested closed around the torus leaves none open, however many kinds the tree configures', examples: ['configure-all'] },
  { key: 'textbook_openapi_contract', lean: 'theorem textbook_openapi_contract (tools : Nat) : tools + 2 - 2 = tools := Nat.add_sub_cancel tools 2', says: 'the standard contract adds nothing the catalogue does not hold: its component schemas are the tools and the two JSON-RPC envelopes, so less the envelopes they are the tools', examples: ['configure-api'] },
  { key: 'textbook_bindings_named_not_valued', lean: 'theorem textbook_bindings_named_not_valued (names : Nat) : names * 0 = 0 := Nat.mul_zero names', says: 'however many binding names a tenant admin selects in Payload, the values held there are none: names times zero values', examples: ['configure-connectors', 'configure-bindings', 'configure-tenant-missing'] },
  { key: 'textbook_access_combinations', lean: 'theorem textbook_access_combinations : 3 * 3 * 4 = 36 := by decide', says: 'three tenant roles, three docket roles and four operations make thirty-six role–operation combinations, each decided by one of three deciders', examples: ['audit-access'] },
  { key: 'textbook_advantage_unbounded', lean: 'theorem textbook_advantage_unbounded (verified : Nat) : verified < verified + 1 := Nat.lt_succ_self verified', says: 'the quantum advantage is unlimited by default: for any count of copies proven by hash there is a greater one, so no bound is set on the measure and none is needed to compute it', examples: ['audit-access', 'metrics-advantage'] },
  { key: 'textbook_merge_commutes', lean: 'theorem textbook_merge_commutes (a b : Nat) : max a b = max b a ∧ max a a = a := ⟨Nat.max_comm a b, Nat.max_self a⟩', says: 'two edits merged by block address commute and merging an edit with itself is that edit: a collision in the involution is a merge, never a refusal', examples: ['payload-merge'] },
  { key: 'textbook_app_doc_blocks', lean: 'theorem textbook_app_doc_blocks : 24 + 1 = 25 := by decide', says: 'an app on request as a lexical document holds one block per generated file and one for the bundle: twenty-three blocks', examples: ['payload-app-lexical'] },
  { key: 'textbook_streams_cover_gateways', lean: 'theorem textbook_streams_cover_gateways : 360 / 60 = 6 ∧ 360 / 90 = 4 ∧ 4 ≤ 6 := by decide', says: 'from the 60-degree angle six streams meet at a point and none collides, while the four 90-degree gateways stay covered: six perspectives over four operations', examples: ['configure-scope', 'payload-merge'] },
  { key: 'textbook_poles_pyramid', lean: 'theorem textbook_poles_pyramid : 6 + 8 - 12 = 2 ∧ 8 / 2 = 4 := by decide', says: 'the poles of the earth as pyramids base to base are the octahedron: six vertices, twelve edges, eight 60-degree faces closed by Euler, four faces to a pole over the four gateways of the equator', examples: ['configure-dependencies'] },
  { key: 'textbook_hologram_rotations', lean: 'theorem textbook_hologram_rotations : 10 * 11 = 110 := by decide', says: 'every block presents its ten program rotations in each of the eleven locales: one hundred and ten SEO pages from one address', examples: ['payload-hologram'] },
  { key: 'textbook_sitemap_capacity', lean: 'theorem textbook_sitemap_capacity : 50000 * 50000 = 2500000000 := by decide', says: 'the sitemap protocol presents fifty thousand URLs a sitemap and fifty thousand sitemaps an index: two and a half billion addresses, every one computed from its UUID', examples: ['payload-hologram'] },
  { key: 'textbook_fractal_scales', lean: 'theorem textbook_fractal_scales : 7 - 1 = 6 := by decide', says: 'the fractal plugin hologram has seven scales of one shape — block, document, page, site, app, tenant, MCP — and six folds between them, each scale addressed by the fold of the one below', examples: ['configure-branding', 'payload-hologram'] },
  { key: 'textbook_widgets_cover_mcp', lean: 'theorem textbook_widgets_cover_mcp : 8 * 2 = 16 := by decide', says: 'eight registry items in two variants are sixteen choices a nibble, so every UUID is one combination of the shadcn widgets and every tool of the MCP is covered by the one core with nothing loaded', examples: ['configure-ui-coverage'] },
  { key: 'textbook_leads_addressed', lean: 'theorem textbook_leads_addressed (a u : Nat) : a + u - u = a := Nat.add_sub_cancel a u', says: 'the leads the theorems address and the leads they do not make the leads: nothing is assigned in advance, and what no theorem reaches stays open', examples: ['leads-by-theorem'] },
  { key: 'textbook_context_balanced', lean: 'theorem textbook_context_balanced (full kept : Nat) (h : kept ≤ full) : full - kept + kept = full := Nat.sub_add_cancel h', says: 'the context balanced to a request: the tokens saved and the tokens kept make the whole list, so what the model carries is the cluster it needs and nothing is lost', examples: ['extend-out-balanced'] },
  { key: 'textbook_billing_complete', lean: 'theorem textbook_billing_complete : 1 + 1 + 1 + 1 = 4 := by decide', says: 'the usage bill is complete when its four accounts are each kept: the tokens, the bits at their thermodynamic cost at the temperature, the time, the coins', examples: ['metrics-bill'] },
  { key: 'textbook_kwh_joules', lean: 'theorem textbook_kwh_joules : 3600 * 1000 = 3600000 := by decide', says: 'a kilowatt-hour is three million six hundred thousand joules: the bill\'s joules priced by the tariff the tenant names link it to the energy sector', examples: ['metrics-bill'] },
  { key: 'textbook_margin_makes_price', lean: 'theorem textbook_margin_makes_price (price cost : Nat) (h : cost ≤ price) : price - cost + cost = price := Nat.sub_add_cancel h', says: 'the margin and the provider\'s cost make the price: the margin is computed from a cost the verifier read, never asserted', examples: ['stripe-margins'] },
  { key: 'textbook_carry_release', lean: 'theorem textbook_carry_release (carried : Nat) : carried = 0 ∨ 0 < carried := Nat.eq_zero_or_pos carried', says: 'the leads carried are zero and the release is published as the next sequential version, or they are positive and next converts them to Payload documents first: no third case', examples: ['leads-carry'] },
  { key: 'textbook_news_adapters', lean: 'theorem textbook_news_adapters : 4 + 3 = 7 := by decide', says: 'four open news APIs and three keyed ones are the seven adapters of the DOI research: the mentions of every record of precedence, by source, measured and never a verdict', examples: ['compete-news-plan'] },
  { key: 'textbook_lean_served_whole', lean: 'theorem textbook_lean_served_whole (hand generated : Nat) : hand + generated - generated = hand := Nat.add_sub_cancel hand generated', says: 'the hand-written theorems and the generated lemmas make what the kernel accepts, and every version serves the whole of it: nothing Lean is hidden', examples: ['textbook-theorems-served', 'metrics-live'] },
  { key: 'textbook_deploy_sets', lean: 'theorem textbook_deploy_sets : 3 * 8 = 24 := by decide', says: 'deploySetsOf renders them and deploySetOf each one: three deploy templates (the Worker, the Payload app, a generated app) over the eight products of the catalogue are twenty-four sets, each a wrangler environment deployed by name beside the default deploy and as usable as direct use', examples: ['configure-wrangler-set', 'configure-deploy-sets'] },
  { key: 'textbook_payload_field_types', lean: 'theorem textbook_payload_field_types : 19 + 4 = 23 := by decide', says: 'Payload\'s field types: nineteen hold a value (text, textarea, number, email, code, json, date, point, checkbox, select, radio, relationship, upload, array, blocks, group, tabs, richText, slug) and four present (row, collapsible, ui, join), twenty-three in all; every schema is built of the nineteen', examples: ['payload-schemas'] },
  { key: 'textbook_payload_operations', lean: 'theorem textbook_payload_operations : 17 + 7 + 12 + 3 + 3 + 6 + 1 + 1 = 50 := by decide', says: 'Payload\'s operations by scope: seventeen on a collection, seven on a global, twelve of auth, three of access, three of preferences, six of the jobs queue, the custom endpoint and the GraphQL endpoint: fifty, each with its local signature, its REST method and path and its GraphQL form', examples: ['payload-schemas'] },
  { key: 'textbook_payload_schemas', lean: 'theorem textbook_payload_schemas : 19 * 17 = 323 := by decide', says: 'every data field type under every collection operation is a schema handled programmatically from the table: 323 schemas, each as JSON Schema 2020-12, a GraphQL type, an MCP tool of the plugin and an OpenAPI path', examples: ['payload-schemas'] },
  { key: 'textbook_payload_queries', lean: 'theorem textbook_payload_queries : 16 * 19 = 304 := by decide', says: 'sixteen where operators over nineteen data field types: 304 queries, every one a schema read through an operator', examples: ['payload-schemas'] },
  { key: 'textbook_payload_hooks', lean: 'theorem textbook_payload_hooks : 1 + 18 + 6 + 5 = 30 := by decide', says: 'the hooks by level: one root hook, eighteen on a collection, six on a global, five on a field: thirty, each firing on the operations it names; the generated plugin uses them for the collision guard, the first user, the app request and the 404 answered from the id', examples: ['payload-schemas'] },
  { key: 'textbook_payload_access', lean: 'theorem textbook_payload_access : 7 + 3 + 3 + 3 = 16 := by decide', says: 'the access functions by level: seven on a collection, three on a global, three on a field, three on the jobs: sixteen, each answering a boolean or a where, the whole of role-based access the tenants carry', examples: ['payload-schemas'] },
  { key: 'textbook_payload_coordination', lean: 'theorem textbook_payload_coordination : 8 * 50 = 400 := by decide', says: 'eight realtime channels (live preview client and server, autosave, document locking, the jobs queue, scheduled publishing, the MCP plugin\'s stream, GraphQL subscriptions: none) over fifty operations are 400 coordinations, every one coordinated by the content address the edit names, no socket of its own', examples: ['payload-schemas'] },
  { key: 'textbook_url_combinations', lean: 'theorem textbook_url_combinations : 2 ^ 4 - 1 = 15 := by decide', says: 'four kinds of cached asset (the generated code, the SDK, the registry items, the examples\' blocks) make fifteen non-empty combinations a URL may name: the fallback for anything, computed in real time and verified at every address', examples: ['match-url-fallback'] },
  { key: 'textbook_licence_chain', lean: 'theorem textbook_licence_chain (n : Nat) : n + 1 - 1 = n := Nat.add_sub_cancel n 1', says: 'n sublicences under one licence are n links of the docket: every reseller\'s Stripe hook writes a licence entry linked to the licence above, so verify walks the chain link by link and the author is paid at the root, by coins on every response and by the catalogue at every grant', examples: ['match-url-fallback'] },
  { key: 'textbook_kind_alphabet', lean: 'theorem textbook_kind_alphabet : 26 + 1 = 27 := by decide', says: 'a kind is written in twenty-six lower-case letters and the dash: twenty-seven symbols, the pattern of the entries\' kind field', examples: ['configure-validations'] },
  { key: 'textbook_sha256_is_64', lean: 'theorem textbook_sha256_is_64 : 256 / 4 = 64 := by decide', says: 'a SHA-256 digest is 256 bits, four to a hex digit: 64 hex digits, the pattern of the entries\' sha256 field', examples: ['configure-validations', 'seal-text', 'match-pattern-seal'] },
  { key: 'textbook_name_alphabets', lean: 'theorem textbook_name_alphabets : 26 + 10 + 1 = 37 := by decide', says: 'a slug (lower-case letters, digits, the dash) and a binding name (upper-case letters, digits, the underscore) are each written in thirty-seven symbols, the patterns of the tenants\' fields', examples: ['configure-validations'] },
  { key: 'textbook_create_hue', lean: 'theorem textbook_create_hue : 432 % 360 = 72 := by decide', says: 'the a432 key read as a hue: 432 degrees around the circle is 72, the theme colour of every shadcn create the QPU answers; the five harmonics give the five chart hues the same way', examples: ['css-create'] },
  { key: 'textbook_coil_green', lean: 'theorem textbook_coil_green : 432 % 360 + 432 / 9 = 120 := by decide', says: 'when coins fuse to coils the colour is green, the heart chakra\'s: the coin\'s a432 hue (72) advanced by a ninth of the key (48) is 120, cyan and yellow full in CMYK', examples: ['css-coil'] },
  { key: 'textbook_scan_stream', lean: 'theorem textbook_scan_stream : 36 * 108 = 432 * 9 := by decide', says: 'the scannable stream: thirty-six frames (one per character of a UUID) of 108 milliseconds (the third harmonic) are 3888 milliseconds, the vortex period (432 × 9); a single frame links nothing, a stream reads the address', examples: ['verify-scan'] },
  { key: 'textbook_phase_bits', lean: 'theorem textbook_phase_bits : 2 ^ 11 ≤ 3888 ∧ 3888 < 2 ^ 12 := by decide', says: 'the phase of the stream at an interaction is one of 3888 milliseconds: eleven bits of randomness a sample, the device\'s own nonce thirty-two more', examples: ['seal-entropy'] },
  { key: 'textbook_scan_links', lean: 'theorem textbook_scan_links : 36 - 1 = 35 := by decide', says: 'a period of the stream is a chain of thirty-five links between its thirty-six frames; every full period streamed is one call, the first the coin, every further one a coil: the fusion', examples: ['verify-scan', 'verify-scan-one-frame'] },
  { key: 'textbook_chain_bits', lean: 'theorem textbook_chain_bits : 32 * 4 = 128 := by decide', says: 'the chain\'s combinatorics: thirty-two hex digits of four bits are 128 bits, 16^32 addresses a stream may link; the rate of usage is counted in periods of that chain', examples: ['verify-scan'] },
  { key: 'textbook_hue_shift', lean: 'theorem textbook_hue_shift (h g s : Nat) : h + s - (g + s) = h - g := Nat.add_sub_add_right h s g', says: 'a program presented by hue and moved by the params keeps every distance between its steps: the rotation by the params\' hue is the same ring at another angle', examples: ['css-program-shift'] },
  { key: 'textbook_hue_steps', lean: 'theorem textbook_hue_steps : 16 * 45 = 2 * 360 := by decide', says: 'sixteen hues 22.5° apart present the sixteen hex digits: sixteen times forty-five is two turns of the circle, the step a half of forty-five; rays set next to each other fit when their seam is above zero', examples: ['css-rays'] },
  { key: 'textbook_cheap_gates', lean: 'theorem textbook_cheap_gates (refusals : Nat) : refusals * 0 = 0 := Nat.mul_zero refusals', says: 'cheap gates leading every violator to court: however many refusals a gate answers, it writes nothing; the case is computed from the refusal and the violator files it through its own MCP', examples: ['legal-court', 'legal-court-rules'] },
  { key: 'textbook_cl_described', lean: 'theorem textbook_cl_described (a b c d : Bool) : (a && b && c && d) = true ↔ (a = true ∧ b = true ∧ c = true ∧ d = true) := by cases a <;> cases b <;> cases c <;> cases d <;> decide', says: 'a commit message is a Google CL description exactly when all four hold: the first line at most 72 characters, its first word an imperative verb, a blank second line, a body; the commit-msg workflow refuses a message missing any one, and names each missing one', examples: ['repository-cl-described', 'repository-cl-one-sentence'] },
  { key: 'textbook_actions_pinned', lean: 'theorem textbook_actions_pinned (u p : Nat) (hu : u = 0) (hp : p = 0) : u + p = 0 := by omega', says: 'a commit or push is pinned exactly when the actions its workflows use by a movable ref (u) and the workflows without least-privilege permissions (p) are both none: the two Scorecard checks Pinned-Dependencies and Token-Permissions, counted over the workflow files the hook reads', examples: ['repository-actions-tag-pinned', 'repository-actions-sha-pinned'] },
  { key: 'textbook_hook_workflows', lean: 'theorem textbook_hook_workflows : 5 + 1 + 1 = 7 := by decide', says: 'five git hooks (pre-commit, commit-msg, pre-push, post-commit, prepare-commit-msg), the CI and the strict pre-deploy check are seven client MCP workflows of one door; the hook script walks the steps and decides nothing', examples: ['repository-workflow', 'repository-probes'] },
  { key: 'textbook_commit_green', lean: 'theorem textbook_commit_green (green skipped : Nat) : green + skipped + 0 = green + skipped := Nat.add_zero (green + skipped)', says: 'when to commit: the flow is green — the steps of the receipt are green and skipped and no red, so adding the red (zero) changes nothing; one red step refuses the commit', examples: ['repository-refuse-commit'] },
  { key: 'textbook_google_one_door', lean: 'theorem textbook_google_one_door (direct : Nat) : direct = 0 ↔ ¬ 0 < direct := by omega', says: 'Google through one door: a commit holds the rule google-via-payload exactly when the direct Google calls it stages (URLs of a GOOGLE_HOST outside the registries and the generated plugin) are zero; every Google call is the qpu-google-call job: the scripts ask it by askGoogle (getOf and discover route every Google host there), the dashboard\'s analytics routes by reportOf, rowsOf, reportBody, answerOf and week, the reCAPTCHA check and the Measurement Protocol by askJob and GOOGLE_ENDPOINTS', examples: ['repository-google-via-payload'] },
  { key: 'textbook_google_call_schema', lean: 'theorem textbook_google_call_schema (unknown missing broken : Nat) : unknown + missing + broken = 0 ↔ unknown = 0 ∧ missing = 0 ∧ broken = 0 := by omega', says: 'a Google call runs exactly when its violations of the Discovery document (GOOGLE_DISCOVERY names where it is read) sum to none, that is when each kind is none: an unknown method or parameter, a required one missing, an enum or pattern broken, a credential from the caller; otherwise the qpu-google-call job records the refusal', examples: ['payload-google-call-validated', 'payload-google-call-endpoint', 'payload-google-call-refused'] },
  { key: 'textbook_violation_one_kind', lean: 'theorem textbook_violation_one_kind (kinds : Nat) (h : 0 < kinds) : (kinds - 1) + 1 = kinds := by omega', says: 'every violation has exactly one kind of the closed set VIOLATION_KINDS (the WORKFLOW_RULES first), the others its kinds − 1, and violationOf gives it the content address of its kind, rule and evidence, so one violation is one record; any violation refuses (severity refuse)', examples: ['repository-violation'] },
  { key: 'textbook_retry_supersedes', lean: 'theorem textbook_retry_supersedes (attempts : List Bool) (last : Bool) : (attempts ++ [last]).getLast? = some last := by simp', says: 'a retried step is its last attempt: whatever the earlier attempts were, the status the green rule reads is the last one, so a step next retried to green no longer refuses the commit; every attempt stays in the receipt as history', examples: ['repository-retry-supersedes'] },
  { key: 'textbook_version_sequential', lean: 'theorem textbook_version_sequential (n : Nat) : n + 1 - 1 = n := Nat.add_sub_cancel n 1', says: 'when to push: the version is the last tag or its one next step (one step forward, one back is the tag), and the build it names is the one the package answers on initialize', examples: ['repository-decide-push', 'configure-versions'] },
  { key: 'textbook_majority_of_three', lean: 'theorem textbook_majority_of_three : 2 * 2 > 3 := by decide', says: 'the e2e gate decodes by majority: two agreeing copies of three decide a combination (twice two exceeds three); a push needs nothing uncorrectable', examples: ['repository-decide-push'] },
  { key: 'textbook_chat_call_or_question', lean: 'theorem textbook_chat_call_or_question (served : Bool) (options : Nat) (h : served = false → 0 < options) : served = true ∨ 0 < options := match served, h with | true, _ => Or.inl rfl | false, h => Or.inr (h rfl)', says: 'every chat turn is a door call or one programmable question with at least one option, never prose: a problem no door decides alone (chatOf) is asked back with the doors around it as its options, the choice re-enters the loop, the routing is measured as exact pairs and misroutes as leads, and the chat is the MCP App ui://qpu/chat, which the React host QpuApp mounts when no tool is named, in the admin and as the registry item qpu-chat; the door is entered only for a chat given as an object (isObj) and every turn is one tools/call envelope (callOf)', examples: ['chat-question', 'chat-choice', 'chat-routes', 'chat-not-object', 'configure-chat-item'] },
  { key: 'textbook_route_or_lead', lean: 'theorem textbook_route_or_lead (b : Bool) : b = true ∨ b = false := by cases b <;> decide', says: 'every prompt is routed to the theorems it reaches by its subject or two specific words, or it is a lead: no third case, the chat answering with the theorems and their examples as routes', examples: ['match-route'] },
  { key: 'textbook_use_completes', lean: 'theorem textbook_use_completes (n k : Nat) : n ≤ n + k := Nat.le_add_right n k', says: 'the more the QPU is used the more complete it gets: every run adds what its sources answered (k) to what it held (n) and loses nothing, the immutable sources answering the same forever', examples: ['leads-sources-plan'] },
  { key: 'textbook_textbooks_partition', lean: 'theorem textbook_textbooks_partition (routed domain outside : Nat) : routed + domain + outside - outside - domain = routed := by omega', says: 'every open textbook is reached by a theorem, a lead of the domain the theorems reach, or outside it: three parts and no fourth', examples: ['leads-sources-judged'] },
  { key: 'textbook_registry_words_searched', lean: 'theorem textbook_registry_words_searched : 3 * 10 = 30 := by decide', says: 'three distinctive words of the lead asked of the public MCP registry, one search each of at most ten servers: thirty related servers at most', examples: ['discover-lead-registry'] },
  { key: 'textbook_discovery_requests', lean: 'theorem textbook_discovery_requests : 1 + 1 + 1 + 52 = 55 := by decide', says: 'the unit\'s tools/list, its catalogue door and its well-known file beside fifty-two verifier contracts are fifty-five discovery requests', examples: ['discover-requests'] },
  { key: 'textbook_wave_requests_by_lead', lean: 'theorem textbook_wave_requests_by_lead : 3 + 2 + 7 * 3 + 1 + 1 = 28 := by decide', says: 'willow-spec\'s three requests, repo-cirq\'s two, three for each of the seven DOIs the tree cites and one for each of two constants are the wave\'s twenty-eight requests', examples: ['wave-requests'] },
  { key: 'textbook_readiness_judged', lean: 'theorem textbook_readiness_judged (served refuted trial leads : Nat) (h : served + refuted + trial = leads) : leads - trial = served + refuted := by omega', says: 'the unit judges every lead: served, refuted or in trial, so the leads less those in trial are the ones it settled, however many leads a run reads', examples: ['readiness-plan'] },
  { key: 'textbook_e2e_combos', lean: 'theorem textbook_e2e_combos : 3 + 3 + 7 = 13 ∧ 6 + 7 = 13 := by decide', says: 'clay\'s three, processor\'s three and roadmap\'s seven combinations are thirteen requests to one host, six dashboard cells and seven examples', examples: ['e2e-requests'] },
  { key: 'textbook_imagine_verdicts', lean: 'theorem textbook_imagine_verdicts : 0 + 2 + 0 = 2 ∧ 169 + 20 = 189 := by decide', says: 'two leads judged, none served, two impossible, none unknown, and their verification requests 169 and 20 are 189', examples: ['imagine-two'] },
  { key: 'textbook_translate_phrases', lean: 'theorem textbook_translate_phrases : 5 + 1 + 0 = 6 := by decide', says: 'six distinct words: five phrases the vocabulary translates (the, lead, served, verdict, unknown), one it knows and keeps (is), none untranslated', examples: ['translate-bg'] },
  { key: 'textbook_vocabulary_measured', lean: 'theorem textbook_vocabulary_measured (terms known : Nat) (h : known ≤ terms) : terms - known + known = terms := Nat.sub_add_cancel h', says: 'every term of a locale\'s vocabulary is known or missing, so the missing and the known make the terms whatever the vocabulary has grown to', examples: ['translate-coverage'] },
  { key: 'textbook_mongo_find_filter', lean: 'theorem textbook_mongo_find_filter : 1 + 2 = 3 ∧ 60 ≤ 105 ∧ 54 < 60 := by decide', says: 'of three documents scanned one matches qubits ≥ 60 with the tag processor (Willow, 105) and two do not (Sycamore at 54 below the bound, Quantum Echoes without the tag)', examples: ['mongo-find'] },
  { key: 'textbook_mongo_update_inc', lean: 'theorem textbook_mongo_update_inc : 54 + 1 = 55 ∧ 1 + 1 = 2 := by decide', says: '$inc adds one to Sycamore\'s 54 qubits: 55, written as a new entry beside the one it links, so history is two entries', examples: ['mongo-update'] },
  { key: 'textbook_checkout_amount_cents', lean: 'theorem textbook_checkout_amount_cents : 432 * 100 = 43200 := by decide', says: 'a yearly licence of 432 euros is 43200 cents, the unit Stripe\'s checkout form takes', examples: ['stripe-plan'] },
  { key: 'textbook_webhook_tolerance', lean: 'theorem textbook_webhook_tolerance : 1700000100 - 1700000000 = 100 ∧ 100 ≤ 300 := by decide', says: 'the signature signed at 1700000000 and checked at 1700000100 is 100 seconds old, within the 300-second tolerance, so the event is valid', examples: ['stripe-webhook'] },
  { key: 'textbook_patent_apis_partition', lean: 'theorem textbook_patent_apis_partition : 2 + 5 = 7 := by decide', says: 'two patent APIs answer in the open and five take a key: seven APIs', examples: ['patents-plan'] },
  { key: 'textbook_mentions_by_source', lean: 'theorem textbook_mentions_by_source : 3 + 2 + 0 = 5 ∧ 2 + 1 = 3 := by decide', says: 'three mentions from hn-algolia, two from crossref-events and none from the unreachable gdelt are five mentions, two sources reachable of three', examples: ['compete-mentions'] },
  { key: 'textbook_legal_plan_calls', lean: 'theorem textbook_legal_plan_calls (claims : Nat) : claims + 2 - claims = 2 := by omega', says: 'the legal plan makes one call per claim the author makes and two more, however many claims the tree carries', examples: ['legal-plan'] },
  { key: 'textbook_repository_watch_leads', lean: 'theorem textbook_repository_watch_leads : 3 + 3 + 3 + 2 + 1 + 1 + 1 = 14 := by decide', says: 'three workflow leads, three branch leads, three tag leads, two release leads, one Zenodo, one workspace and one npm lead: fourteen leads', examples: ['repository-watch'] },
  { key: 'textbook_orcid_digits', lean: 'theorem textbook_orcid_digits : 4 * 4 + 3 = 19 := by decide', says: 'an ORCID is sixteen digits in four groups of four with three dashes: nineteen characters, the author\'s @id the block carries', examples: ['jsonld-block'] },
  { key: 'textbook_catalogue_offers', lean: 'theorem textbook_catalogue_offers : 1 + 3 + 2 + 3 = 9 := by decide', says: 'one free offer, three yearly, two monthly and three metered are the catalogue\'s nine offers', examples: ['jsonld-catalogue'] },
  { key: 'textbook_codes_locales', lean: 'theorem textbook_codes_locales : 1 + 10 = 11 := by decide', says: 'English and the ten locales the vocabulary translates into are the eleven locales the codes tool validates', examples: ['codes-plan'] },
  { key: 'textbook_scopes_tenants_collections', lean: 'theorem textbook_scopes_tenants_collections : 3 * 4 = 12 ∧ 3 + 3 = 6 := by decide', says: 'three tenants over four scoped collections are twelve tenant scopes, and three tenant roles beside three docket roles are six roles', examples: ['configure-scopes'] },
  { key: 'textbook_qpu_fields', lean: 'theorem textbook_qpu_fields : 6 + 9 = 15 := by decide', says: 'six fields of the entries collection and nine of the qpu block are the fifteen fields QPU adds to Payload', examples: ['configure-fields'] },
  { key: 'textbook_entry_operations', lean: 'theorem textbook_entry_operations : 3 + 1 = 4 := by decide', says: 'an entry has four operations: three granted by role (read, create, delete) and update to no one, because an entry is its content address', examples: ['configure-access'] },
  { key: 'textbook_actions_experience', lean: 'theorem textbook_actions_experience : (2 * 507 * 100 + 546) / (2 * 546) = 93 ∧ max 120 (max 140 110) = 140 ∧ 1000 / 140 = 7 := by decide', says: '507 involutions of 546 copies round to a free share of 93 percent, and the slowest host\'s 140 ms median shards a batch to 1000 / 140 = 7 calls', examples: ['configure-actions'] },
  { key: 'textbook_fullstack_hooks', lean: 'theorem textbook_fullstack_hooks : 3 + 2 = 5 := by decide', says: 'three hook entries on entries (the address on create, the 404 healed after an error, none on change) and two on pages (revalidate after change, the collision guard before change) are five over two collections', examples: ['configure-hooks'] },
  { key: 'textbook_wrangler_drift', lean: 'theorem textbook_wrangler_drift : 12 - 2 = 10 ∧ 5 ≤ 10 := by decide', says: 'of the Worker configuration\'s twelve top-level paths the client\'s text agrees on two (name, main), so ten drift, each an open lead, at least the five the example asks', examples: ['configure-wrangler-drift'] },
  { key: 'textbook_branding_sources', lean: 'theorem textbook_branding_sources : 3 + 2 = 5 := by decide', says: 'the branding\'s five fields are three the user defined in the admin (name, accent, logo) and two still computed (tagline, icon)', examples: ['configure-branding-user'] },
  { key: 'textbook_attest_facets', lean: 'theorem textbook_attest_facets : 4 - 1 = 3 ∧ 2 * 1 * 1 = 2 := by decide', says: 'the attest tool has four facets, one free (hosts), three enumerable whose spaces 2 · 1 · 1 make its two cells (plan, read)', examples: ['dashboard-attest'] },
  { key: 'textbook_theorems_plan_steps', lean: 'theorem textbook_theorems_plan_steps (theorems backed : Nat) (h1 : 10 ≤ theorems) (h2 : 10 ≤ backed) : 1 + 1 + 1 + 1 = 4 ∧ 20 ≤ theorems + backed := by omega', says: 'the plan that replaces the textbook\'s axioms by theorems through the Payload MCP is four steps, over at least ten theorems and ten backed examples', examples: ['payload-theorems-plan'] },
  { key: 'textbook_axioms_replaced', lean: 'theorem textbook_axioms_replaced : 1 + 1 = 2 ∧ 2 - 1 = 1 := by decide', says: 'two qpu blocks read, one already naming its theorem and one an axiom: the axiom replaced, one update request', examples: ['payload-theorems-update'] },
  { key: 'textbook_app_fields_validated', lean: 'theorem textbook_app_fields_validated : 3 + 1 = 4 ∧ 2 + 1 = 3 := by decide', says: 'the streamed form\'s four fields are three that pass (name, host, variant) and one refused (env), whose three names are two the stack knows (D1, R2) and one unknown (NOPE)', examples: ['payload-app-validate'] },
  { key: 'textbook_site_documents', lean: 'theorem textbook_site_documents (pages gates categories docs : Nat) (h : docs = pages + (gates + categories + 1)) : docs - pages = gates + categories + 1 := by omega', says: 'the site\'s documents are its use-case pages and the gate pages, and the gate pages are every gate, every category and the root: one document each, whatever the number of gates', examples: ['payload-site'] },
  { key: 'textbook_extend_inward', lean: 'theorem textbook_extend_inward (mine : Nat) : mine + 1 - mine = 1 := by omega', says: 'the catalogue extended inward is the tree\'s own tools and the one door the docs add, whatever the number of tools', examples: ['extend-in-docs'] },
  { key: 'textbook_foreign_door_name', lean: 'theorem textbook_foreign_door_name : 23 + 1 + 31 = 55 := by decide', says: 'a foreign door is named by its host, a colon and its tool: docs.mcp.cloudflare.com (23 characters), \':\' and search_cloudflare_documentation (31), fifty-five characters', examples: ['extend-call-served'] },
  { key: 'textbook_attest_requests', lean: 'theorem textbook_attest_requests : 7 + 1 = 8 := by decide', says: 'the eight crypto and certificate APIs are seven the client requests over HTTP and one, the live TLS certificate, the client reads itself on four hosts', examples: ['attest-plan'] },
  { key: 'textbook_textbook_categories', lean: 'theorem textbook_textbook_categories (examples toolboxes : Nat) (h1 : 49 ≤ examples) (h2 : 8 ≤ toolboxes) (h3 : toolboxes ≤ 12) : 1 + 1 + 1 + 1 = 4 ∧ toolboxes ≤ examples := by omega', says: 'the textbook is categorised four ways, by toolbox, tool, theorem and module, and it holds more examples than toolboxes', examples: ['textbook-categories'] },
  { key: 'textbook_processor_cells', lean: 'theorem textbook_processor_cells : 3 ^ 1 = 3 ∧ 3 - 3 = 0 := by decide', says: 'the processor tool\'s one facet of three devices (Willow, Sycamore, Sycamore23) admits three combinations, every one a final cell, none left open', examples: ['dashboard-processor'] },
  { key: 'textbook_shor_narrowed_cells', lean: 'theorem textbook_shor_narrowed_cells : 21 - 3 + 1 = 19 ∧ 100000 < 280896 := by decide', says: 'with the name fixed to shor the next facet open is N in [3, 21]: nineteen cells, none final, while the whole space counts 280,896 combinations, above the hundred thousand the example asks', examples: ['dashboard-algorithm-narrowed'] },
  { key: 'textbook_dashboard_spaces', lean: 'theorem textbook_dashboard_spaces : 2 * 2 * 2 * 2 * 5 = 80 ∧ 7 * 19 * 1 * 2 * 6 * 1 * 1 * 8 * 2 * 11 = 280896 := by decide', says: 'the input space of a tool is the product of its enumerable facets: leads 2 · 2 · 5 = 20 (carry, byTheorem, status), algorithm 7 · 19 · 1 · 2 · 6 · 1 · 1 · 8 · 2 · 11 = 280,896', examples: ['dashboard-index'] },
  { key: 'textbook_willow_holds_codes', lean: 'theorem textbook_willow_holds_codes : 101 ≤ 105 ∧ 103 ≤ 105 ∧ 347 < 400 := by decide', says: 'Willow\'s 105 qubits hold the distance-7 code\'s 101 and the random-circuit application\'s 103, and its stated average connectivity 3.47 is below the typical 4 (hundredths)', examples: ['processor-willow'] },
  { key: 'textbook_sycamore_couplers', lean: 'theorem textbook_sycamore_couplers : 2 * 88 = 176 ∧ 176 ≤ 4 * 54 := by decide', says: 'Sycamore\'s 88 couplers have 176 ends among its 54 qubits, within the four neighbours a grid qubit has at most', examples: ['processor-sycamore'] },
  { key: 'textbook_hadamard_amplitudes', lean: 'theorem textbook_hadamard_amplitudes : 2 ^ 1 = 2 ∧ 1 * 1 + 1 * 1 = 2 := by decide', says: 'one qubit has two amplitudes, and a Hadamard sets each to 1/√2, whose squares (one half each) sum to one: 1 + 1 halves are 2 halves', examples: ['circuit-hadamard-amplitudes'] },
  { key: 'textbook_hadamard_histogram', lean: 'theorem textbook_hadamard_histogram : 207 + 193 = 400 := by decide', says: 'the Hadamard measured 400 times reads 0 in 207 shots and 1 in 193: the histogram partitions the 400 bitstrings', examples: ['circuit-hadamard-sampled'] },
  { key: 'textbook_bit_flip_purity', lean: 'theorem textbook_bit_flip_purity : 1 * 1 + 9 * 9 = 82 ∧ 1 + 9 = 10 ∧ 10 * 10 = 100 := by decide', says: 'an X under a bit flip of p = 0.1 leaves probabilities 0.1 and 0.9, summing to one, and purity 0.1² + 0.9² = 0.82 (in hundredths: 1 + 81 = 82 of 100)', examples: ['circuit-bit-flip-noise'] },
  { key: 'textbook_echo_qubits_within_willow', lean: 'theorem textbook_echo_qubits_within_willow : 65 ≤ 103 ∧ 103 ≤ 105 := by decide', says: 'Quantum Echoes as Google states it ran on Willow: the 65 qubits of the figure within the 103 of the text, within Willow\'s 105', examples: ['echo-benchmark'] },
  { key: 'textbook_roadmap_decades', lean: 'theorem textbook_roadmap_decades : 100 * 10 ^ 4 = 1000000 ∧ 1 + 5 = 6 ∧ 50000 * 10 ^ 3 = 50000000 := by decide', says: 'the six milestones are the first (54 physical qubits) and five decades from 100 to 1,000,000 (100 · 10⁴), and the four application bands run contiguous from 50,000 to 50,000,000 physical qubits (50,000 · 10³)', examples: ['roadmap-all'] },
  { key: 'textbook_roadmap_milestone_three', lean: 'theorem textbook_roadmap_milestone_three : 10 ^ 3 = 1000 ∧ 3 ≤ 6 ∧ 50000 * 10 ^ 3 = 50000000 := by decide', says: 'milestone three of the six is one long-lived logical qubit from 10³ = 1000 physical qubits, and the four application bands span three decades, 50,000 to 50,000,000 physical qubits', examples: ['roadmap-milestone-3'] },
  { key: 'textbook_shor_fifteen_order', lean: 'theorem textbook_shor_fifteen_order : 7 ^ 1 % 15 = 7 ∧ 7 ^ 2 % 15 = 4 ∧ 7 ^ 3 % 15 = 13 ∧ 7 ^ 4 % 15 = 1 ∧ Nat.gcd (4 - 1) 15 = 3 ∧ Nat.gcd (4 + 1) 15 = 5 ∧ 3 * 5 = 15 := by decide', says: 'the powers of 7 modulo 15 run 7, 4, 13, 1: the order is 4, and gcd(7² − 1, 15) = 3 and gcd(7² + 1, 15) = 5 are the factors, 3 × 5 = 15', examples: ['algorithm-shor-15'] },
  { key: 'textbook_qft_three_amplitudes', lean: 'theorem textbook_qft_three_amplitudes : 2 ^ 3 = 8 ∧ 8 * 1250 = 10000 := by decide', says: 'the QFT on three qubits has 2³ = 8 amplitudes, each of probability 12.50%: eight times 1250 basis points make the whole', examples: ['algorithm-qft-3'] },
  { key: 'textbook_grover_one_iteration', lean: 'theorem textbook_grover_one_iteration : 2 ^ 2 = 4 ∧ (2 * 1 + 1) * 30 = 90 := by decide', says: 'two qubits hold 2² = 4 items, the start sits 30° from the unmarked plane, and one iteration turns it by (2·1 + 1)·30° = 90°: the marked |00⟩ with certainty', examples: ['algorithm-grover'] },
  { key: 'textbook_teleport_three_qubits', lean: 'theorem textbook_teleport_three_qubits : 1 + 2 = 3 ∧ 2 ^ 2 = 4 := by decide', says: 'one message qubit and a Bell pair of two are the three qubits; the two measured bits choose one of 2² = 4 corrections, and the three Pauli expectations X, Y, Z agree', examples: ['algorithm-teleportation'] },
  { key: 'textbook_phase_three_bits', lean: 'theorem textbook_phase_three_bits : 2 * 4 = 2 ^ 3 ∧ 2 < 2 ^ 3 := by decide', says: 'θ = 1/4 is 2/2³: two of the eight values three bits can hold, so phase estimation reads it exactly', examples: ['algorithm-phase-estimation'] },
  { key: 'textbook_qaoa_random_cut', lean: 'theorem textbook_qaoa_random_cut : 409 + 191 + 80 + 91 + 337 + 439 + 269 + 332 + 161 + 71 + 338 + 280 + 109 + 92 + 176 = 3375 ∧ 33750 = 2 * 16875 := by decide', says: 'the fifteen edge weights of the Cirq page\'s instance sum to 33.75, and the expected cut of 16.875 is half of it, the random baseline', examples: ['algorithm-qaoa'] },
  { key: 'textbook_software_cirq_implemented', lean: 'theorem textbook_software_cirq_implemented : 1 + 4 = 5 := by decide', says: 'of the five tools of the Software page, one (Cirq) is implemented here and four are named', examples: ['software'] },
  { key: 'textbook_statements_one_topic', lean: 'theorem textbook_statements_one_topic : 1 + 41 = 42 := by decide', says: 'one statement is chosen by its topic of the forty-two the statements tool holds', examples: ['statements-cirq'] },
  { key: 'textbook_repositories_by_language', lean: 'theorem textbook_repositories_by_language : 11 + 3 + 1 = 15 := by decide', says: 'the fifteen quantumlib repositories are eleven in Python, three in C++ and one in OpenQASM', examples: ['repositories'] },
  { key: 'textbook_leads_by_status', lean: 'theorem textbook_leads_by_status (served partly blocked outside opened total : Nat) (h : served + partly + blocked + outside + opened = total) : total - opened = served + partly + blocked + outside := by omega', says: 'every lead has one of five statuses: the leads less the open ones are the ones followed, served, partial, blocked or out of scope, whatever the count of the run', examples: ['leads-all'] },
  { key: 'textbook_repetition_code_tenth', lean: 'theorem textbook_repetition_code_tenth : 3 * 10 - 2 = 28 ∧ 28 < 100 ∧ 3 + 2 = 5 := by decide', says: 'at p = 1/10 the repetition code fails with 3p² − 2p³ = (3·10 − 2)/10³ = 28/1000, below the raw 100/1000, on three data and two syndrome qubits', examples: ['qec-bit-flip-0.1'] },
  { key: 'textbook_h2_below_hartree_fock', lean: 'theorem textbook_h2_below_hartree_fock : 11167 < 11373 ∧ 11373 - 11167 = 206 ∧ 1 + 2 + 1 + 1 = 5 := by decide', says: 'H₂ on two qubits is five Pauli terms (I, Z0, Z1, Z0Z1, X0X1); the variational minimum −1.1373 Ha lies 0.0206 Ha below the Hartree–Fock −1.1167 Ha', examples: ['chemistry-h2'] },
  { key: 'textbook_ftqc_t_counts', lean: 'theorem textbook_ftqc_t_counts : 2 * 3 + 1 * 7 + 1 * 1 + 7 * 3 + 12 * 1 + 3 * 7 = 68 := by decide', says: 'the six circuits cost 68 T gates: the QFT two controlled-S at three, Grover one Toffoli at seven, teleportation one T, Shor seven controlled-S at three, QAOA twelve T, the repetition cycle three Toffolis at seven', examples: ['ftqc-all'] },
  { key: 'textbook_cirq_exports', lean: 'theorem textbook_cirq_exports : 7 + 3 + 9 + 10 = 29 ∧ 6 + 9 = 15 := by decide', says: 'this tree\'s Cirq is twenty-nine exports, seven classes, three qubit constructors, nine gates and ten functions, and six of the fifteen quantumlib repositories are emulated', examples: ['quantumlib-cirq'] },
  { key: 'textbook_clay_register_width', lean: 'theorem textbook_clay_register_width : 2 ^ 32 = 4294967296 ∧ 4294967296 < 2 ^ 33 ∧ 2 * 16 < 33 ∧ 33 ≤ 3 * 16 := by decide', says: 'the widest value of the register, the amplitudes 2³² = 4294967296, needs 33 bits: more than two 16-bit limbs, within three', examples: ['clay-register'] },
  { key: 'textbook_seal_and_content_decided', lean: 'theorem textbook_seal_and_content_decided : 31 + 1 = 32 ∧ 2 + 2 = 4 ∧ 0x70a13419 + 0x8f5ecbe6 = 0xffffffff := by decide', says: 'the seal is decided from 31 of the 32 nibbles, the content by one fold: two checks decided of four, and the address and its σ₁₅ mirror sum nibble by nibble to f', examples: ['verify-seal-and-content'] },
  { key: 'textbook_tamper_one_nibble', lean: 'theorem textbook_tamper_one_nibble : 11 - 10 = 1 ∧ 2 ≠ 6 ∧ 1 + 3 = 4 := by decide', says: 'one nibble changed, a (10) to b (11), moves the decided version to 6 against the stated 2: the seal alone decides, one check of four, no content needed', examples: ['verify-tampered'] },
  { key: 'textbook_willow_distance_seven', lean: 'theorem textbook_willow_distance_seven : 7 * 7 + (7 * 7 - 1) = 97 ∧ 97 < 101 ∧ 101 ≤ 105 := by decide', says: 'Willow\'s 105 qubits hold the 101 its distance-7 code uses, 97 of them the code\'s 49 data and 48 measure qubits', examples: ['match-willow'] },
  { key: 'textbook_glagolitic_fifteen', lean: 'theorem textbook_glagolitic_fifteen : 10 + 5 = 15 ∧ 3 * 5 = 15 := by decide', says: 'the Glagolitic numeral Ⰺⰴ is 10 + 5 = 15, factored 3 × 5 in the reflection', examples: ['match-glagolitic'] },
  { key: 'textbook_bulgarian_statement_words', lean: 'theorem textbook_bulgarian_statement_words : 2 + 1 + 1 = 4 ∧ 10 + 5 = 15 := by decide', says: 'the Bulgarian statement is four words: two translated by vocabulary, the name Shor kept untranslated, and the numeral Ⰺⰴ read as 10 + 5 = 15', examples: ['match-bulgarian'] },
  { key: 'textbook_fold_pieces_under_bound', lean: 'theorem textbook_fold_pieces_under_bound : 10 + 7 + 11 + 12 = 40 ∧ 40 - 12 = 28 ∧ 10 ≤ 12 ∧ 7 ≤ 12 ∧ 11 ≤ 12 ∧ 12 ≤ 12 := by decide', says: 'the 40-byte text exceeds the 12-byte bound by 28 and folds into four pieces of 10, 7, 11 and 12 bytes, each within the bound', examples: ['match-pattern-fold'] },
  { key: 'textbook_dashboard_algorithm_combinations', lean: 'theorem textbook_dashboard_algorithm_combinations : 7 * 19 * 1 * 2 * 6 * 1 * 1 * 8 * 2 * 11 = 280896 ∧ 1000 < 280896 := by decide', says: 'the algorithm tool\'s ten enumerable facets (7 names, 19 N, 1 a, 2 sweep, 6 qubits, 1 input, 1 θ, 8 bits, 2 repetitions, 11 nodes) multiply to 280896 combinations, above a thousand', examples: ['match-pattern-dashboard'] },
  { key: 'textbook_rsa_beyond_bound', lean: 'theorem textbook_rsa_beyond_bound : 2 ^ 4 < 21 ∧ 21 < 2 ^ 5 ∧ 5 < 2048 := by decide', says: 'the simulator\'s bound N ≤ 21 is a five-bit number, and an RSA-2048 modulus has 2048 bits', examples: ['match-rsa-2048'] },
  { key: 'textbook_audit_all_pass', lean: 'theorem textbook_audit_all_pass (passed failed total : Nat) (h : passed + failed = total) (h0 : failed = 0) : passed = total := by omega', says: 'the audit replays every check: when none fails every check passes, however many checks the tree has grown to', examples: ['audit-self'] },
  { key: 'textbook_axioms_linked', lean: 'theorem textbook_axioms_linked (examples linked : Nat) (h : linked = examples) : examples - linked = 0 := by omega', says: 'every axiom of the textbook has its theorem: when every example is linked to a kernel-accepted theorem, the examples left without one are none', examples: ['textbook-axioms'] },
  { key: 'textbook_collision_solves_many', lean: 'theorem textbook_collision_solves_many (k : Nat) (h : 2 ≤ k) : 1 < k ∧ 1 ≤ k - 1 := by omega', says: 'a subject shared by k problems, two at least, is one missing theorem that serves more than one problem, and every one of them collides with at least one other: each problem solves many others', examples: ['leads-collide'] },
  { key: 'textbook_double_torus', lean: 'theorem textbook_double_torus (n : Nat) : n < n + 1 ∧ n + 1 - 1 = n := by omega', says: 'the quantum core computes on the classical world only through coins fused into coils, and the classical world reaches it only the same way back: two loops of one double torus, every crossing a finite step with always a next and one step back', examples: ['stripe-fusion'] },
  { key: 'textbook_leaks_redacted', lean: 'theorem textbook_leaks_redacted (found redacted : Nat) (h : redacted = found) : found - redacted = 0 := by omega', says: 'problem solving requires problem finding (the one allowance shared with purify, LEAK_ALLOWED): every leak found in what is published is reported by its kind and place and redacted, so none of its values is repeated, however many are found', examples: ['audit-leaks', 'audit-leak-allowed'] },
  { key: 'textbook_expressions_evaluate', lean: 'theorem textbook_expressions_evaluate (closed held : Nat) (h : held = closed) : closed - held = 0 := by omega', says: 'every textbook expression is a tool: when each closed statement evaluated exactly agrees with what the kernel proved, none disagrees, and every number the prose states rests on one of them or is a lead', examples: ['textbook-expressions', 'textbook-prose'] },
  { key: 'textbook_queneau_compositions', lean: 'theorem textbook_queneau_compositions : 10 ^ 14 = 100000000000000 ∧ 365 * 24 * 60 = 525600 ∧ 10 ^ 14 / 525600 = 190258751 ∧ 10 ^ 14 % 525600 = 474400 := by decide', says: 'Queneau\'s combinatorics (Cent mille milliards de poèmes, 1961): ten choices on each of fourteen strips are 10^14 compositions, and read at one minute each, with years of 365 days of 1440 minutes, they take 190,258,751 years and 474,400 minutes more', examples: ['textbook-queneau', 'textbook-prose-queneau'] },
  { key: 'textbook_mixed_radix', lean: 'theorem textbook_mixed_radix (q r d : Nat) (h : d < r) : (d + r * q) % r = d ∧ (d + r * q) / r = q := ⟨by rw [Nat.add_mul_mod_self_left, Nat.mod_eq_of_lt h], by rw [Nat.add_mul_div_left _ _ (by omega), Nat.div_eq_of_lt h, Nat.zero_add]⟩', says: 'every composition is computed from its index and back: a choice below its position\'s number of choices comes out of the number it made, the remainder the choice and the quotient the rest, so one primitive covers every combination space and stores none', examples: ['fold-queneau'] },
  { key: 'textbook_decode_not_search', lean: 'theorem textbook_decode_not_search : 14 < 10 ^ 14 ∧ 14 * 1 = 14 := by decide', says: 'decoding is algebra, not search: a composition of fourteen positions of ten choices is decoded in fourteen steps, one per position, where trying candidates would take up to 10^14; a one-way address is never searched, and the formulas that decode are free for all', examples: ['fold-decode', 'fold-decode-one-way'] },
  { key: 'textbook_tamper_detected', lean: 'theorem textbook_tamper_detected : 256 / 2 = 128 ∧ 10 ^ 38 < 2 ^ 128 := by decide', says: 'tampering is covered by the digest, not by refusing to search: a block\'s SHA-256 has 256 bits, so even a crafted collision takes about 2^128 trials, more than 10^38, while any modified copy is caught by one comparison and answered with the court\'s case', examples: ['seal-tamper-authentic'] },
  { key: 'textbook_artifacts_verified', lean: 'theorem textbook_artifacts_verified (verified mismatched unreached total : Nat) (h : verified + mismatched + unreached = total) (hm : mismatched = 0) : total - unreached = verified := by omega', says: 'every public artifact downloaded is verified or a mismatch, and every one not reached is measured again: when none mismatches, every artifact reached verifies against the digest its registry recorded, however many are published', examples: ['seal-artifacts'] },
  { key: 'textbook_machine_allow_list', lean: 'theorem textbook_machine_allow_list (asked allowed : Nat) (h : allowed ≤ asked) : asked - allowed + allowed = asked := Nat.sub_add_cancel h', says: 'every action asked of the developer machine is run because the allow-list names it and the rules allow it, or refused with the court\'s case: the refused and the run make every request, no third', examples: ['repository-machine-actions', 'repository-machine-refused', 'repository-machine-push-unconfirmed', 'repository-machine-worktree-unconfirmed', 'repository-machine-tag-confirmed', 'repository-machine-commit-deferred'] },
  { key: 'textbook_stream_no_silence', lean: 'theorem textbook_stream_no_silence (gap beat : Nat) (h : gap ≤ beat) (hb : beat ≤ 1000) : gap ≤ 1000 := Nat.le_trans h hb', says: 'while work runs the stream is never silent for more than a second: a heartbeat follows any second without an event, so every gap between two events is within the heartbeat, and the heartbeat is one second', examples: ['repository-status-no-silence'] },
  { key: 'textbook_eta_from_receipts', lean: 'theorem textbook_eta_from_receipts (a q x : Nat) (h : a ≤ q) : a * x + (q - a) * x = q * x := by rw [← Nat.add_mul, Nat.add_sub_of_le h]', says: 'forecastOf: an ETA is the forecast of the recorded times, estimated and labelled so, or absent when none is recorded: exponential smoothing in exact rationals weighs each time a/q and the level (q - a)/q, the weights sum to q, so equal recorded times forecast exactly that time; the interval is the one-step errors at 95 %, and the forecast is the step\'s budget', examples: ['repository-status-eta', 'repository-status-forecast'] },
  { key: 'textbook_neighbour_step', lean: 'theorem textbook_neighbour_step (x y : Nat) (hx : x < 65536) (hy : y < 4096) : ((x + 1) % 65536 + 65535) % 65536 = x ∧ ((y + 1) % 4096 + 4095) % 4096 = y := by omega', says: 'neighboursOf: one step in program space moves g1 by one modulo 2^16 or g2, g3 by one modulo 2^12 (their stamp nibble decided, never walked), and the step back returns the program, at every edge of the torus', examples: ['fold-neighbours'] },
  { key: 'textbook_build_fresh', lean: 'theorem textbook_build_fresh (built source : Nat) (h : source ≤ built) : built - source + source = built := Nat.sub_add_cancel h', says: 'a deploy carries a bundle no older than its sources: the build\'s time is at or after the last source change, or the bundle is rebuilt', examples: ['repository-predeploy'] },
  { key: 'textbook_bindings_bound', lean: 'theorem textbook_bindings_bound (needed declared missing : Nat) (h : declared + missing = needed) (h0 : missing = 0) : declared = needed := by omega', says: 'every binding the adapters need is declared and every resource it names exists in the account: when none is missing, the declared are the needed, however many the adapters bind', examples: ['repository-predeploy'] },
  { key: 'textbook_observed_errors', lean: 'theorem textbook_observed_errors (errors requests : Nat) (h : errors * 1000 ≤ requests) : errors ≤ requests := by omega', says: 'the deployed Worker observed: at most one server error in a thousand requests, as the account\'s observability records it, so the errors never outnumber the requests', examples: ['repository-predeploy'] },
  { key: 'textbook_bill_covered', lean: 'theorem textbook_bill_covered (price cost : Nat) (h : cost ≤ price) : price - cost + cost = price := Nat.sub_add_cancel h', says: 'the minimum bill of existing and computing (zero within the free tiers, the paid base beyond them) is covered by the cheapest licence of the catalogue: the licence is the bill and the margin of the quantum framework', examples: ['repository-predeploy'] },
  { key: 'textbook_ports_cover', lean: 'theorem textbook_ports_cover (complete blocked total : Nat) (h : complete + blocked = total) : total - blocked = complete := by omega', says: 'every combination of the adapters ported onto Cloudflare is complete or names the missing link that blocks it: the combinations less the blocked ones are the complete ones, however many adapters the app grows to', examples: ['configure-adapters-port'] },
  { key: 'textbook_harmonic_default', lean: 'theorem textbook_harmonic_default (n k : Nat) (h : 0 < n) : k % n < n := Nat.mod_lt k h', says: 'harmonic options by default: the referrer\'s address, or the a432 key, reduced modulo the number of combinations a schema\'s enums hold is always below that number, so the default it names is always one of the combinations', examples: ['fold-harmonic', 'payload-hooks-collapse'] },
  { key: 'textbook_rbac_options', lean: 'theorem textbook_rbac_options (allowed all : Nat) (h : allowed ≤ all) : all - allowed + allowed = all := Nat.sub_add_cancel h', says: 'a role sees a part of every enum\'s superposition: the combinations it may choose and the ones it may not make all of them, and its harmonic default is always one it may choose; in the app one predicate, adminOf, reads the admin role for every access function', examples: ['fold-harmonic-rbac'] },
  { key: 'textbook_free_or_coil', lean: 'theorem textbook_free_or_coil (calls free : Nat) (h : free ≤ calls) : calls - free + free = calls := Nat.sub_add_cancel h', says: 'every call is free or a coil, decided by the licence: only the pure algebraic formulas are free, every other call is covered by the licence and billed by the coins; the free and the coils make the calls', examples: ['metrics-bill', 'repository-penalty-way'] },
  { key: 'textbook_authorship_tracked', lean: `theorem textbook_authorship_tracked : ${PRECEDENCE.filter((p) => p.doi === '10.5281/zenodo.23156998').length} = 1 ∧ ${PRECEDENCE.filter((p) => p.doi === '10.1086/468061').length} = 0 := by decide`, says: 'the author\'s records, counted from the tree\'s PRECEDENCE table, hold the QPU\'s DOI once and Gneezy and Rustichini\'s not at all', examples: ['match-doi-own', 'match-doi-external'] },
  { key: 'textbook_lead_cells', lean: 'theorem textbook_lead_cells (i : Nat) (h : i < 432) : 2 ^ 4 * 3 ^ 3 = 432 ∧ 2 * 2 * 2 * 2 * 3 * 3 * 3 = 432 ∧ 432 % 432 = 0 ∧ i % 2 + 2 * (i / 2 % 2) + 4 * (i / 4 % 2) + 8 * (i / 8 % 2) + 16 * (i / 16 % 3) + 48 * (i / 48 % 3) + 144 * (i / 144 % 3) = i := by refine ⟨by decide, by decide, by decide, ?_⟩; omega', says: 'combinationsOf: a432 builds every lead combination — the key 432 is 2⁴ · 3³, the product of the seven radices [2, 2, 2, 2, 3, 3, 3]; the a432 key reduced mod 432 names cell 0; and every cell below 432 read as its mixed-radix digits and encoded again is itself, so every lead lands in exactly one cell', examples: ['leads-combinations'] },
  { key: 'textbook_session_partition', lean: 'theorem textbook_session_partition (c : Nat) (h : c < 4) : c = 0 ∨ c = 1 ∨ c = 2 ∨ c = 3 := by omega', says: 'sessionOf: every directive of every session lands in exactly one of four classes — folded into an Open work item, proposed as a new one, acted on where it was said once, or an assent — so the four counts sum to the directives read', examples: ['leads-session'] },
  { key: 'textbook_sitemap_leads', lean: 'theorem textbook_sitemap_leads (u v c l : Nat) (h : v + (u - v) = u) (k : c + l = v) : c + l + (u - v) = u := by omega', says: 'sitemapLeadsOf: every url of a sitemap (sitemaps.org: loc, lastmod) is refused by name, covered by a hand-written lead, or a lead of its own — the three counts sum to the urls handed over, so nothing the site lists is dropped', examples: ['leads-sitemap'] },
  { key: 'textbook_rosetta_conventions', lean: 'theorem textbook_rosetta_conventions (n : Nat) : (n % 10 + (10 - n % 10) % 10) % 10 = 0 ∧ 1 + (n - 1) % 9 + (10 - (1 + (n - 1) % 9)) = 10 ∧ 3432 % 9 = 3 ∧ 3432 % 10 = 2 ∧ 15 % 9 ≠ 15 % 10 := by refine ⟨by omega, by omega, by decide, by decide, by decide⟩', says: 'the Clay rosetta: the unit seeds a value by its last decimal digit and the tree by its digital root; σ₁₀ holds on both sides for every n, and the two conventions name the same seed exactly when n mod 9 and n mod 10 agree (3432: 3 against 2; 15: 6 against 5), a difference of convention, never of error', examples: ['clay-rosetta'] },
  { key: 'textbook_binding_zero_hex_path', lean: 'theorem textbook_binding_zero_hex_path : 2 + 1 + 2 + 1 + 36 = 42 ∧ 16 * 16 = 256 ∧ 256 * 256 = 65536 := by decide', says: 'binding 0 is the filesystem: hexPathOf puts a document at ab/cd/<uuid>, two hex digits, a slash, two more, a slash and the 36 characters of its address, 42 in all, the R2 key and the GCS object of the same document; 256 folders a level, 65 536 at the second; Payload\'s qpu-raid plugin (qpuRaid) writes each version once through binding0Of with a pointer to the latest and reads back only what its address verifies; RAID_ORDER puts binding 0 last on every profile, so raidRead and leadsOf always have a place to read when Payload does not answer', examples: ['raid-binding0-mirror', 'raid-binding0-restore'] },
]
/** A sentence made safe inside a Lean doc comment: Lean block comments nest, so an opening /- or a closing -/ in the prose would open or end one early; both are parted by a space. */
export const leanDocOf = (s: string) => s.replace(/\/-/g, '/ -').replace(/-\//g, '- /')
export const TEXTBOOK_LEAN = (): string => ['/-! # Qpu.Textbook', 'The textbook\'s axioms replaced by theorems: every arithmetic relation an example asserts, stated so the kernel checks it.', 'GENERATED by scripts/gen-docs.ts from src/quantum/textbook-theorems.ts; edit the table, never this file. -/', '', ...TEXTBOOK_THEOREMS.map((t) => `/-- ${leanDocOf(t.says)} (examples: ${t.examples.join(', ') || 'none yet'}) -/\n${t.lean}`), ''].join('\n')
